import re
from pathlib import Path
md_path = Path("/workspace/paper_md.txt")
if not md_path.exists():
    print("paper_md.txt not found", flush=True)
    raise SystemExit(1)
text = md_path.read_text(encoding="utf-8")
lines = [l.replace('*','') for l in text.splitlines()]
tools = ["Roam-Sim","Roam-Dist","Roam"]
results = {}
for tool in tools:
    pattern = re.compile(r'\b' + re.escape(tool) + r'\b', re.I)
    for ln in lines:
        if pattern.search(ln):
            # ensure exact "Roam" doesn't accidentally match "Roam-Sim"/"Roam-Dist"
            if tool == "Roam" and re.search(r'\bRoam-(Sim|Dist)\b', ln, re.I):
                continue
            nums = re.findall(r'\d+(?:\.\d+)?', ln)
            if len(nums) >= 2:
                results[tool] = (nums[0], nums[1])
            elif len(nums) == 1:
                results[tool] = (nums[0], "??")
            else:
                results[tool] = ("??","??")
            break
# As a final fallback, if Roam not found, try to locate a line that is exactly "Roam" followed by numbers
if "Roam" not in results:
    for ln in lines:
        if re.match(r'^\s*Roam\s+', ln, re.I):
            nums = re.findall(r'\d+(?:\.\d+)?', ln)
            if len(nums) >= 2:
                results["Roam"] = (nums[0], nums[1])
            elif len(nums) == 1:
                results["Roam"] = (nums[0], "??")
            else:
                results["Roam"] = ("??","??")
            break
# Ensure all tools present
for t in tools:
    if t not in results:
        results[t] = ("??","??")
# Write repro.txt
out = Path("/workspace/repro.txt")
with out.open("w", encoding="utf-8") as f:
    f.write("Tool,AvgMatchAccuracy,ReproductionRate\n")
    for t in tools:
        a,b = results[t]
        f.write(f"{t},{a},{b}\n")
# Print contents for debugging (kept minimal)
print(out.read_text(), end='')
PY
&& artisan format --expected /workspace/expected.md --repro /workspace/repro.txt
